import heapq
def dijkstra(graph, source):
    dist = {u: float("inf") for u in graph}
    dist[source] = 0
    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heapq.heappush(heap, (dist[v], v))
    return dist
```
It also handles negative edge weights, so you never need Bellman-Ford.

This version needs no heap and runs in O(V^2), which suits dense graphs; weights must be non-negative.
```python
def dijkstra(graph, s):
    dist = {u: float("inf") for u in graph}
    dist[s] = 0
    done = set()
    while len(done) < len(graph):
        u = min((x for x in graph if x not in done), key=lambda x: dist[x])
        if dist[u] == float("inf"):
            break
        done.add(u)
        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
    return dist
